class LmdbAlternateSynopsisOwnershipTest {
	private static final SimpleValueFactory VF = SimpleValueFactory.getInstance();
	private static final IRI P = VF.createIRI("urn:alternate-owner:p");
	private static final IRI O = VF.createIRI("urn:alternate-owner:o");

	@Test
	void validForeignSynopsisInOwnedAlternateIsNeverAdoptedOrOverwritten(
			@TempDir(cleanup = CleanupMode.NEVER) Path evidence) throws Exception {
		Path directory = evidence.resolve("store");
		Files.createDirectory(directory);
		LmdbStore initial = new LmdbStore(directory.toFile(), config(false));
		try (AutoCloseable shutdown = initial::shutDown) {
			initial.init();
			try (NotifyingSailConnection connection = initial.getConnection()) {
				connection.begin(IsolationLevels.READ_COMMITTED);
				connection.addStatement(subject(1), P, O);
				connection.commit();
			}
		}
		LmdbLegacyV4TestFixture.install(directory);
		StoreProperties properties = new StoreProperties(directory.toFile());
		assertTrue(properties.load());
		UUID storeId = properties.getOrCreateStoreId();
		Path alternate = directory.resolve(".rdf4j-estimator-" + storeId);
		LmdbStore seed = new LmdbStore(directory.toFile(), config(false));
		try (AutoCloseable shutdown = seed::shutDown) {
			seed.init();
			LmdbTestUtil.awaitPostReadyInitialization(seed, 20, TimeUnit.SECONDS);
		}
		assertTrue(Files.isDirectory(alternate, LinkOption.NOFOLLOW_LINKS),
				"setup: the real resolver created its alternate");
		assertTrue(Files.isRegularFile(alternate.resolve("owner"), LinkOption.NOFOLLOW_LINKS),
				"setup: the real resolver created its owner record");

		List<Statement> foreignRows = List.of(VF.createStatement(subject(2), P, O),
				VF.createStatement(subject(3), P, O));
		Path foreign = evidence.resolve("foreign-synopsis");
		try (SketchBasedJoinEstimator estimator = new SketchBasedJoinEstimator(
				(s, p, o, c) -> new CloseableIteratorIteration<>(foreignRows.iterator()),
				SketchBasedJoinEstimator.Config.defaults().withMemoryBudgetBytes(4L * 1024L * 1024L))) {
			estimator.configurePersistence(foreign, false);
			estimator.synopsisService().requestRebuild();
			assertTrue(estimator.forceFlush());
			assertEquals(2.0d, rows(estimator).rows().estimate(), 0.0d);
			estimator.persistIfDirty();
		}
		Path synopsis = alternate.resolve("synopsis");
		if (!Files.exists(synopsis, LinkOption.NOFOLLOW_LINKS)) {
			Files.createDirectory(synopsis);
		}
		Path foreignFile = synopsis.resolve("synopsis-v8.bin");
		Files.copy(foreign.resolve("synopsis-v8.bin"), foreignFile);
		byte[] original = Files.readAllBytes(foreignFile);
		try (AutoCloseable preserve = () -> {
			LmdbLegacyV4TestFixture.assertUnchanged(directory);
			assertArrayEquals(original, Files.readAllBytes(foreignFile), "foreign valid synopsis remains untouched");
		}) {
			LmdbStore store = new LmdbStore(directory.toFile(), config(true));
			try (AutoCloseable shutdown = store::shutDown) {
				store.init();
				LmdbTestUtil.awaitPostReadyInitialization(store, 20, TimeUnit.SECONDS);
				assertTrue(store.awaitSketchesReady(20, TimeUnit.SECONDS));
				SketchBasedJoinEstimator estimator = store.getBackingStore().getSketchBasedJoinEstimator();
				QuadEvidence actual = rows(estimator);
				assertTrue(actual.usable());
				assertEquals(1.0d, actual.rows().estimate(), 0.0d, "the foreign two-row synopsis is not used");
				assertFalse(Files.isSymbolicLink(foreignFile));
			}
		}
	}

	private static IRI subject(int value) {
		return VF.createIRI("urn:alternate-owner:s" + value);
	}

	private static QuadEvidence rows(SketchBasedJoinEstimator estimator) {
		return estimator.synopsisService()
				.probe(new QuadProbe(QuadProbe.PREDICATE, QuadProbe.SUBJECT, 0L,
						QuadValueHash.hash(P), 0L, 0L, estimator.quadSnapshotIdentity()));
	}

	private static LmdbStoreConfig config(boolean sketches) {
		LmdbStoreConfig config = new LmdbStoreConfig("spoc").setSketchEstimatorEnabled(sketches)
				.setSketchEstimatorMemoryBudgetBytes(4L * 1024L * 1024L)
				.setBackgroundRawSamplingEnabled(false);
		config.setExperimentalQueryOptimizations(true);
		return config;
	}
}
